"""Rebuild PIMoE validation reports/figures from saved arrays only."""
if __name__ == '__main__':
    raise SystemExit('LEGACY_EXCLUDED_FROM_CURRENT_PROJECT: historical result generation is archived')
import argparse,json,csv,math
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

def read(p):return json.loads(Path(p).read_text())
def table(p):return list(csv.DictReader(Path(p).open()))
def save(fig,C,name):
 fig.tight_layout()
 for ext in ['png','pdf']:fig.savefig(C/'figures'/f'{name}.{ext}',dpi=300)
 plt.close(fig)
def main():
 p=argparse.ArgumentParser();p.add_argument('--campaign',required=True);a=p.parse_args();C=Path(a.campaign).resolve();s=read(C/'reports/specialization_summary.json');routing=table(C/'reports/routing.csv');con=table(C/'reports/contribution_summary.csv');regional=table(C/'reports/regional_calibration.csv');arrays=np.load(C/'evaluations/expert_arrays.npz');stages=sorted({int(x['stage']) for x in routing});usage=np.array([[np.mean([float(x['alpha_'+str(e)]) for x in routing if int(x['stage'])==t]) for e in range(4)] for t in stages]);js=arrays['pairwise_JS']
 fig,ax=plt.subplots(figsize=(7,4));ax.stackplot(stages,usage.T,labels=['E0','E1','E2','E3']);ax.set(xlabel='Completed experiments',ylabel='Mean posterior membership mass',ylim=(0,1));ax.legend(ncol=4);save(fig,C,'router_utilization_by_stage')
 fig,ax=plt.subplots(figsize=(5,4));im=ax.imshow(usage.T,aspect='auto',vmin=0,vmax=1);ax.set(xticks=range(len(stages)),xticklabels=stages,yticks=range(4),yticklabels=['E0','E1','E2','E3'],xlabel='Completed experiments',ylabel='Expert');fig.colorbar(im,ax=ax,label='Posterior mass');save(fig,C,'expert_assignment_heatmap')
 fig,ax=plt.subplots(figsize=(5,4));im=ax.imshow(js,vmin=0,vmax=math.log(2));ax.set(xticks=range(4),yticks=range(4),xlabel='Expert',ylabel='Expert');fig.colorbar(im,ax=ax,label='Mean Jensen–Shannon divergence (nats)')
 for i in range(4):
  for j in range(4):ax.text(j,i,f'{js[i,j]:.3f}',ha='center',va='center',color='white' if js[i,j]<.35 else 'black')
 save(fig,C,'expert_distribution_similarity')
 fig,axes=plt.subplots(1,2,figsize=(10,4));pit=arrays['full_PIT'].flatten();q=np.linspace(0,1,101);axes[0].plot(q,[np.mean(pit<=x) for x in q],label='Full PIMoE');axes[0].plot(q,q,'k--');axes[0].set(xlabel='Predictive CDF quantile',ylabel='Empirical fraction');axes[0].legend();axes[1].bar(range(4),[np.mean([float(x['region_coverage90']) for x in regional if int(x['expert'])==e]) for e in range(4)]);axes[1].axhline(.9,color='k',linestyle='--');axes[1].set(xlabel='Expert',ylabel='Regional 90% predictive coverage');save(fig,C,'predictive_calibration')
 fig,axes=plt.subplots(1,2,figsize=(10,4));axes[0].scatter(arrays['expert_predictive_means'][:,0],arrays['expert_predictive_means'][:,3],s=8,alpha=.5);axes[0].set(xlabel='E0 predictive mean',ylabel='E3 predictive mean');axes[1].scatter([float(x['response_variance']) for x in routing],[float(x['alpha_3']) for x in routing],s=8,alpha=.5);axes[1].set(xlabel='Posterior variance of physical response',ylabel='E3 membership mass');save(fig,C,'expert_function_and_responsibility')
 reference=read(C/'reference/reports/final_evaluation.json');result=C/'location/seed101/single/eval/result.json';official=[dict(model='PIMoE',EIG=reference['EIG'],MC_SE=reference['MC_SE'],seed=101)]
 if result.exists():
  x=read(result);official.append(dict(model='Matched single',EIG=x['EIG'],MC_SE=x['MC_SE'],seed=101))
 fig,ax=plt.subplots(figsize=(6,4));ax.bar([r['model'] for r in official],[r['EIG'] for r in official],yerr=[1.96*r['MC_SE'] for r in official]);ax.set_ylabel('EIG (nats),95% trajectory MC intervals')
 if not result.exists():ax.set_title('Matched single official evaluation pending')
 save(fig,C,'pimoe_vs_single_EIG')
 # Show only actual available seed observations; no synthetic five-seed distribution.
 fig,ax=plt.subplots(figsize=(6,4));ax.scatter([101],[reference['EIG']],label='PIMoE observed seed101');ax.set(xlabel='Training seed',ylabel='Official EIG (nats)',title='Only completed evaluations shown');ax.legend();save(fig,C,'training_seed_performance_available')
 num=read(C/'reports/entropy_resolution_summary.json') if (C/'reports/entropy_resolution_summary.json').exists() else {};matched=read(C/'reports/matched_control_independent_summary.json') if (C/'reports/matched_control_independent_summary.json').exists() else []
 full=next(x for x in con if x['mode']=='full');uniform=next(x for x in con if x['mode']=='uniform_membership');remove=next(x for x in con if x['mode']=='remove_1')
 text=['# Expert specialization: frozen seed101','',f"28held-out belief states,4independent diagnostic episodes,336candidates,seed1006. Model unchanged: {s['checkpoint_sha256']}.",'',f"Mean expert mass: {s['mean_alpha']}. Effective expert count {s['mean_effective_experts']:.3f}; max-alpha>0.95 in {100*s['collapse_fraction']:.2f}% of candidates. Soft assignment is not expert sampling or action selection.",'',f"Function outputs differ: pairwise meanJS range {min(js[np.triu_indices(4,1)]):.5f}–{max(js[np.triu_indices(4,1)]):.5f}nats. Identical-region-input head check: {num.get('same_input_head_JS_mean','pending')}. Independent initial weights alone are not used as evidence.",'','## Routing and contribution','',f"Full NLL {full['NLL']} vs uniform-membership {uniform['NLL']}; ranking {full['ranking_accuracy']} vs {uniform['ranking_accuracy']}. Full EIG RMSE {full['EIG_RMSE']} vs uniform {uniform['EIG_RMSE']}. Learned routing improves these NLL/ranking measurements but not every information-error metric.",'',f"RemovingE1 changes EIG RMSE to {remove['EIG_RMSE']}, ranking to {remove['ranking_accuracy']}, NLL to {remove['NLL']}. This is counterfactual distribution shift, not definitive causal necessity evidence. No retraining/removal was adopted.",'','Regional calibration is in regional_calibration.csv. Raw regional NLL cannot be compared as if all regions had equal intrinsic entropy. Responsibility correlations are descriptive, clustered within only4episodes; no exploration/exploitation labels or significance claims.','', '## Numerical information check','',json.dumps(num,indent=2),'','The full-model information error on new on-policy states exceeds the original0.15nat diagnostic tolerance. Preserve this validation limitation; do not claim universal credible EIG estimation or release unnecessary replication before resolving the gate without tuning the frozen model.','', '## Questions answered','', '1.Functionally different:yes on this diagnostic set. 2.Assignments correlate with physical-response uncertainty/candidate/stage; exact descriptive correlations saved. 3.Consistent across seeds:unverified. 4.Learned routing helps NLL/ranking relative to uniform, but not every metric. 5.Parameter-matched single superiority requires the controlled results below and official paired evaluation. 6.Sequential-EIG translation pending. 7.Extra work includes587Mdiagnostic forward-stage evaluations; timing and original phase-accounting limitations disclosed. 8.Four experts are not yet empirically justified. 9.Keep the frozen model as a research reference, not as proof that4experts are necessary. 10.Cross-seed reproducibility, causal specialization and generality remain unsupported.']
 (C/'reports/PIMOE_EXPERT_SPECIALIZATION.md').write_text('\n'.join(text))
 controlmeta=read(C/'location/seed101/single/reports/training_metadata.json');oldmoe=read(C/'reference/reports/final_development_validation.json')['summary'];control=read(C/'location/seed101/single/reports/development.json')['summary']
 (C/'reports/PIMOE_SINGLE_EXPERT_COMPARISON.md').write_text('# Matched single predictive control\n\nOne control satisfies bothA/B:1head,96/96tanh,12Gaussian components,13860parameters versus4heads+router13800parameters (0.435%difference). Same saved simulator/posterior data and same14000update schedule, including the phase-boundary Adam reset. It replaces only the predictive model; Bayesian inference/candidates/lookahead/horizon/officialbank stay unchanged.\n\nOriginal heldout development comparison:\n'+json.dumps(dict(pimoe=oldmoe,single=control),indent=2)+'\n\nIndependent on-policy diagnostic comparison:\n'+json.dumps(matched,indent=2)+'\n\nCost:\n'+json.dumps(controlmeta,indent=2)+'\n\nOfficial single evaluation: '+(json.dumps(read(result),indent=2) if result.exists() else 'PENDING. No final paired improvement claim.')+'\n\nEqual nominal operations are not equal RTX4090/5080walltime. Measured hardware-specific times are kept separate; old reference dataset time is conservatively credited, never reported as free.\n')
 (C/'reports/PIMOE_MULTI_SEED_RESULTS.md').write_text('# Multi-seed status\n\nOnly original PIMoE seed101 has a completed official EIG evaluation. It is reused without retraining. Matched-control101training complete; official evaluation pending unless result.json exists. Seeds102–105 remain HOLD until initial controlled comparison and numerical information-readiness checks are validated. No across-training-seed SD, five-seed confidence interval or consistent expert-index specialization is claimed.\n\nPrepared protocol retains exact original predictive loss, networks, Adam and2k+12kphase schedule. Original training/heldout datasets (fixed1004/1005) are reused, with independent model-initialization/replay seeds102–105. Any resulting seed variance is conditional on that common training dataset; it does not estimate variation from independently regenerated datasets. Reference preparation/model work is attributed to every run and physical reuse separately disclosed. Original and new numerical gates are never bypassed to obtain favorable seeds.\n')
 print(json.dumps(dict(mean_mass=s['mean_alpha'],effective_experts=s['mean_effective_experts'],matched_comparison=matched,information_resolution=num,official_single_complete=result.exists()),indent=2))
if __name__=='__main__':main()
